SELECT mcplocl.*, ssc.name AS steel_classification_name, sscm.keyword AS specification_prefix_type, mbp.id AS process_id, mbp.name AS process_name FROM mes_contract_project_laying_off_config_link mcplocl LEFT JOIN sys_steel_classification ssc ON ssc.id = mcplocl.steel_classification_id LEFT JOIN sys_steel_classification_match sscm ON sscm.bool_delete_enum = FALSE AND sscm.steel_id = mcplocl.steel_classification_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcplocl.process) > 0 WHERE mcplocl.bool_delete_enum = FALSE
AND mcplocl.contract_project_id = #{projectId}
AND mcplocl.statistics_config_statistics_mode = #{statisticsConfigStatisticsMode}

SELECT
    count(0)
FROM mes_contract_project_laying_off_config_link mcplocl
WHERE mcplocl.bool_delete_enum = FALSE

    AND mcplocl.contract_project_id = #{projectId}


    AND mcplocl.statistics_config_statistics_mode = #{statisticsConfigStatisticsMode}

SELECT mcplocl.*, ssc.name AS steel_classification_name, sscm.keyword AS specification_prefix_type, mbp.id AS process_id, mbp.name AS process_name, mcplocld.id as detail_id, mcplocld.create_time as detail_create_time, mcplocld.update_time as detail_update_time, mcplocld.bool_delete_enum as detail_bool_delete_enum, mcplocld.version as detail_version, mcplocld.contract_project_laying_off_config_link_id as detail_contract_project_laying_off_config_link_id, mcplocld.comparison_operator_one as detail_comparison_operator_one, mcplocld.number_one as detail_number_one, mcplocld.comparison_operator_two as detail_comparison_operator_two, mcplocld.number_two as detail_number_two, mcplocld.organization_inside_price as detail_organization_inside_price, mcplocld.organization_outside_price as detail_organization_outside_price FROM mes_contract_project_laying_off_config_link mcplocl LEFT JOIN mes_contract_project_laying_off_config_link_detail mcplocld ON mcplocld.bool_delete_enum = FALSE AND mcplocld.contract_project_laying_off_config_link_id = mcplocl.id LEFT JOIN sys_steel_classification ssc ON ssc.id = mcplocl.steel_classification_id LEFT JOIN sys_steel_classification_match sscm ON sscm.bool_delete_enum = FALSE AND sscm.steel_id = mcplocl.steel_classification_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcplocl.process) > 0
mcplocl.bool_delete_enum = FALSE AND ssc.product_classification_enum = 8 AND mcplocl.contract_project_id = #{contractProjectId}
AND ssc.steel_plate_type_enum IN (
#{steelPlateTypeEnum}
)
