SELECT mcplocl.*, ssc.name AS steel_classification_name, sscm.keyword AS specification_prefix_type, mbp.id AS process_id, mbp.name AS process_name FROM mes_contract_project_laying_off_config_link mcplocl LEFT JOIN sys_steel_classification ssc ON ssc.id = mcplocl.steel_classification_id LEFT JOIN sys_steel_classification_match sscm ON sscm.bool_delete_enum = FALSE AND sscm.steel_id = mcplocl.steel_classification_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcplocl.process) > 0 WHERE mcplocl.bool_delete_enum = FALSE
